const STEPS = [
  { title: 'Simple cubic', n: 'Lattice points sit only at the eight corners. In the space-filling model the gray spheres touch along the cube edges, so the edge length equals two atomic radii.', t: 'sc', r: 1 },
  { title: 'Shrink the spheres', n: 'Pulling the spheres back to small balls shows that the space-filling model and the dot diagram above mark exactly the same eight positions.', t: 'sc', r: 0.3 },
