];
let stepIdx = 0;
const elTitle = document.getElementById('stepTitle');
const elNarr = document.getElementById('stepNarr');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setCellType(s.t, true);
  radFrac = s.r;
  elRadius.value = String(s.r);
  elRadVal.textContent = s.r.toFixed(2);
  elTitle.textContent = `${stepIdx + 1}/${STEPS.length} · ${s.title}`;
  elNarr.textContent = s.n;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx < 0 ? 0 : stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx < 0 ? 0 : stepIdx + 1));

/* ── per-frame tween ───────────────────────────────────────────────────── */
function setOpacity(mesh, o) {
  const t = o < 0.995;
  if (mesh.material.transparent !== t) { mesh.material.transparent = t; mesh.material.needsUpdate = true; }
  mesh.material.opacity = o;
}
