    highlighted.mesh.getWorldPosition(_wp);
    clipMesh.position.copy(_wp);
    clipMesh.scale.setScalar(Math.max(highlighted.r * 1.005, 1e-3));
    clipMesh.visible = true;
    fracLbl.pos.copy(_wp).add(new THREE.Vector3(0, highlighted.r * 0.9 + 0.25, 0));
