    m.renderOrder = 1;
    botG.add(m);
    const a = { mesh: m, role, col, colIdx: ci, r: 0.001 };
    atoms.push(a); col.atoms.push(a);
    const frac = role === 'corner' ? '1/8' : role === 'face' ? '1/2' : '1';
    registerInteractive(m, {
      title: role === 'corner' ? 'Corner atom' : role === 'face' ? 'Face-centered atom' : 'Body-centered atom',
      tooltip: `${frac} of this atom is inside the ${col.name.toLowerCase()} cell`,
      body: role === 'corner'
        ? 'Eight cells meet at a cube corner, so only one octant (1/8) of this atom belongs to this unit cell.'
        : role === 'face'
          ? 'Two cells share a face, so exactly half of this atom belongs to this unit cell.'
          : 'The body-center atom lies completely inside the cell and counts as one whole atom.',
      onClick: () => setHighlight(a)
    });
    return a;
  }
  for (const c of CORNERS) makeAtom(c, 'corner');
  if (col.key === 'bcc') makeAtom(new THREE.Vector3(0, 0, 0), 'body');
  if (col.key === 'fcc') for (const f of FACEPOS) makeAtom(f, 'face');
}

/* ── in-cell fraction solid (sphere clipped to its own cube) ───────────── */
const CLIP = [
  new THREE.Plane(new THREE.Vector3(-1, 0, 0), 0),
  new THREE.Plane(new THREE.Vector3( 1, 0, 0), 0),
  new THREE.Plane(new THREE.Vector3(0, -1, 0), 0),
  new THREE.Plane(new THREE.Vector3(0,  1, 0), 0),
  new THREE.Plane(new THREE.Vector3(0, 0, -1), 0),
  new THREE.Plane(new THREE.Vector3(0, 0,  1), 0)
];
const clipMesh = new THREE.Mesh(SPHERE_GEO, new THREE.MeshStandardMaterial({
  color: 0xffc23d, emissive: 0x6b4a00, roughness: 0.3, metalness: 0.0,
  side: THREE.DoubleSide, clippingPlanes: CLIP
}));
clipMesh.renderOrder = 2;
clipMesh.visible = false;
scene.add(clipMesh);

/* ── camera: cabinet oblique, front-on (after all geometry) ────────────── */
setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: 45,
  depthScale: 0.5,
  axisScreenAngles: null,
  heightFraction: 0.78
});

/* ── labels ────────────────────────────────────────────────────────────── */
addLabel('<b>Lattice point locations</b>', new THREE.Vector3(0, 4.15, 0), { fontSize: '15px' });
addLabel('<b>Cubic unit cells</b>',        new THREE.Vector3(0, 0.45, 0), { fontSize: '15px' });
for (const col of COLS) {
  col.caption = addLabel('<b>' + col.name + '</b>',
    new THREE.Vector3(col.x, -4.25, 0), { fontSize: '13.5px' });
}
const fracLbl = addLabel('', new THREE.Vector3(0, 0, 0), {
  fontSize: '12px', color: '#7a4a00', background: 'rgba(255,255,255,0.93)'
});
fracLbl.div.style.opacity = '0';

/* ── UI state ──────────────────────────────────────────────────────────── */
let selected = 'sc';
let radFrac = 1.0;
let highlighted = null;

const elCounts = document.getElementById('counts');
const elClick  = document.getElementById('clickInfo');
const elRadVal = document.getElementById('radVal');
const elRadius = document.getElementById('radius');
const btns = {
  sc:  document.getElementById('btnSC'),
  bcc: document.getElementById('btnBCC'),
  fcc: document.getElementById('btnFCC')
};

function countsHTML(k) {
  if (k === 'sc')
    return 'corners: 8 × 1/8 = <b>1</b><br>faces: 0 &nbsp;·&nbsp; body: 0<br><b>Total = 1 atom / unit cell</b><br><span style="color:#666">contact along the cube edge, r = a/2</span>';
  if (k === 'bcc')
    return 'corners: 8 × 1/8 = <b>1</b><br>body: 1 × 1 = <b>1</b><br><b>Total = 2 atoms / unit cell</b><br><span style="color:#666">contact along the body diagonal, r = √3·a/4</span>';
  return 'corners: 8 × 1/8 = <b>1</b><br>faces: 6 × 1/2 = <b>3</b><br><b>Total = 4 atoms / unit cell</b><br><span style="color:#666">contact along the face diagonals, r = √2·a/4</span>';
}

function setSelected(k, keepStep) {
  selected = k;
  for (const key in btns) btns[key].classList.toggle('active', key === k);
  elCounts.innerHTML = countsHTML(k);
  for (const col of COLS) {
    col.caption.div.style.color = col.key === k ? '#111' : '#8a8f96';
  }
  if (!keepStep) stepIdx = -1;
}
for (const key in btns) btns[key].addEventListener('click', () => setSelected(key));

elRadius.addEventListener('input', () => {
  radFrac = parseFloat(elRadius.value);
  elRadVal.textContent = radFrac.toFixed(2);
  stepIdx = -1;
});

/* ── click-to-see-the-fraction ─────────────────────────────────────────── */
function setHighlight(a) {
  highlighted = a;
  setSelected(a.col.key, true);
  const cx = a.col.x;
  CLIP[0].constant =  cx + HH;  CLIP[1].constant = -(cx - HH);
  CLIP[2].constant =  BOTY + HH; CLIP[3].constant = -(BOTY - HH);
  CLIP[4].constant =  HH;        CLIP[5].constant =  HH;
  const frac  = a.role === 'corner' ? '1/8' : a.role === 'face' ? '1/2' : '1';
  const words = a.role === 'corner' ? 'one octant' : a.role === 'face' ? 'one hemisphere' : 'the whole sphere';
  const total = a.col.key === 'sc' ? '1' : a.col.key === 'bcc' ? '2' : '4';
  elClick.innerHTML =
    `<b>${a.role === 'corner' ? 'Corner' : a.role === 'face' ? 'Face-centered' : 'Body-centered'} atom — ${a.col.name}</b><br>` +
    `The gold solid is ${words}: <b>${frac}</b> of this atom lies inside the cell.<br>` +
    `Cell total: <b>${total}</b> atoms.`;
  fracLbl.div.innerHTML = `<b>${frac}</b> of this atom is inside`;
  fracLbl.div.style.opacity = '1';
}
function clearHighlight() {
  highlighted = null;
  clipMesh.visible = false;
  fracLbl.div.style.opacity = '0';
  elClick.innerHTML = 'Click any sphere (bottom row) to see how much of it lies <i>inside</i> its cell.';
}
canvas.addEventListener('click', (e) => {
  if (typeof _firstInteractiveHit === 'function' && !_firstInteractiveHit(e)) clearHighlight();
});

/* ── guided tour ───────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Simple cubic', t: 'sc', r: 1,
    n: 'Lattice points sit only at the eight corners. In the space-filling model the gray spheres touch along the cube edges, so the edge length equals two atomic radii.' },
  { title: 'Shrink the spheres', t: 'sc', r: 0.3,
    n: 'Pulling every sphere back to a small ball shows that the space-filling models and the dot diagrams above mark exactly the same lattice positions.' },
  { title: 'Body-centered cubic', t: 'bcc', r: 1,
    n: 'One extra lattice point (red dot) appears at the centre of the cube. The orange body-center atom touches all eight corner atoms along the body diagonal: 8 × 1/8 + 1 = 2 atoms per cell.' },
  { title: 'Face-centered cubic', t: 'fcc', r: 1,
    n: 'Red lattice points now sit at the centre of every face. Each orange face atom is shared by two cells: 8 × 1/8 + 6 × 1/2 = 4 atoms per cell, with contact along the face diagonals.' }
];
let stepIdx = 0;
const elTitle = document.getElementById('stepTitle');
const elNarr  = document.getElementById('stepNarr');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setSelected(s.t, true);
  radFrac = s.r;
  elRadius.value = String(s.r);
  elRadVal.textContent = s.r.toFixed(2);
  elTitle.textContent = `${stepIdx + 1}/${STEPS.length} · ${s.title}`;
  elNarr.textContent = s.n;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx < 0 ? 0 : stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx < 0 ? 0 : stepIdx + 1));

/* ── per-frame tweening ────────────────────────────────────────────────── */
function setOpacity(mat, o) {
  const t = o < 0.995;
  if (mat.transparent !== t) { mat.transparent = t; mat.needsUpdate = true; }
  mat.opacity = o;
}
const _wp = new THREE.Vector3();

function tick() {
  requestAnimationFrame(tick);

  for (const col of COLS) {
    const tf = col.key === selected ? 1 : 0.35;
    col.focus += (tf - col.focus) * 0.15;
    const f = col.focus;

    for (const m of col.topCube.faceMats) setOpacity(m, 0.55 * (0.45 + 0.55 * f));
    for (const m of col.botCube.faceMats) setOpacity(m, 0.50 * (0.45 + 0.55 * f));
    setOpacity(col.topCube.edgeMat, 0.35 + 0.65 * f);
    setOpacity(col.botCube.edgeMat, 0.35 + 0.65 * f);
    for (const dm of col.dots) setOpacity(dm.material, 0.30 + 0.70 * f);

    const targetR = col.rmax * radFrac;
    for (const a of col.atoms) {
      a.r += (targetR - a.r) * 0.16;
      a.mesh.scale.setScalar(Math.max(a.r, 1e-3));
      let o = 0.35 + 0.65 * f;
      if (highlighted) o *= (a === highlighted) ? 0.28 : (a.colIdx === highlighted.colIdx ? 0.35 : 0.5);
      setOpacity(a.mesh.material, o);
    }
  }

  if (highlighted) {
    highlighted.mesh.getWorldPosition(_wp);
    clipMesh.position.copy(_wp);
    clipMesh.scale.setScalar(Math.max(highlighted.r * 1.006, 1e-3));
    clipMesh.visible = true;
    fracLbl.pos.copy(_wp).add(new THREE.Vector3(0, highlighted.r * 0.95 + 0.22, 0));
  }
}
tick();

/* ── initial state ─────────────────────────────────────────────────────── */
setSelected('sc', true);
goToStep(0);
